class Counter:
    def __init__(self):
        self.value = 0

    def step(self, requested):
        self.value = requested
        return self.value

verification_tests:
from target import *
def _counter_forward():
    counter = Counter()
    return [counter.step(1), counter.step(3)]

def _counter_same():
    counter = Counter()
    return [counter.step(1), counter.step(1)]


def test_experience_1():
    assert _counter_same() == [1, 2]


def test_experience_2():
    assert Counter().step(5) == 5


def test_experience_3():
    assert _counter_forward() == [1, 3]
